    /// <summary>
    /// The location of <paramref name="length"/> characters at <paramref name="offset"/> inside a string literal's value.
    /// Falls back to the whole literal when the source text and the value differ (escapes, verbatim, raw or interpolated
    /// strings) or the span does not fit the value.
    /// </summary>
    public static Location InStringLiteral(LiteralExpressionSyntax literal, int offset, int length)
    {
        var token = literal.Token;
        var plain = token.IsKind(SyntaxKind.StringLiteralToken)
                    && token.Text.Length == token.ValueText.Length + 2
                    && token.Text[0] == '"';
