        return Location.Create(literal.SyntaxTree, new TextSpan(token.SpanStart + 1 + offset, length));
    }

    /// <summary>
    /// A location in a non-C# file, such as an <see cref="AdditionalText"/>, with line and column computed from
    /// <paramref name="text"/>. The span is clamped to the text.
