        start = Math.Max(0, Math.Min(start, text.Length));
        length = Math.Max(0, Math.Min(length, text.Length - start));
        var span = new TextSpan(start, length);
        return Location.Create(path, span, text.Lines.GetLinePositionSpan(span));
    }

    /// <summary>The location of <paramref name="file"/> at <paramref name="start"/>; <see cref="Location.None"/> when its text cannot be read.</summary>
